def decimal_to_binary(n):
    """Converts a non-negative integer to its binary representation wrapped with 'db' prefix and suffix.
    Returns the string in format 'db<binary>db'. Returns None for invalid input."""
    if not isinstance(n, int):
        return None
    if n < 0:
        return None
    binary_str = bin(n)[2:]
    return f"db{binary_str}db"

